import os
import datetime
from taf.gnb.oam.megazone_client import megazone_client
from taf.ul.sc.gnb.oam.rest.generic_oam import GenericOAM, web_connection_decorator
from taf.ul.sc.unix_functionality import UnixFunctionality
from taf.ul.sc.exceptions import MegazoneFunctionalityNotSupported


class MegaZoneOAM(GenericOAM):
    def __init__(self, oam_ip, mrbts_id=None, nrbts_id=None):
        super(MegaZoneOAM, self).__init__(oam_ip=oam_ip, mrbts_id=mrbts_id, nrbts_id=nrbts_id)
        self.connection = megazone_client()

    def connect_to_webui(self):
        """
        Connect to 5G BTS Element Manager.

        :return: None
        """

        web_url = 'https://{}'.format(self.oam_ip)
        self.connection.create_session(base_url=web_url)

    def disconnect_webui(self):
        """
        Disconnect from 5G BTS Element Manager.

        :return: None
        """
        self.connection.teardown_session()

    @web_connection_decorator
    def get_bts_info(self, session=None, attribute=None, timeout=None):
        """
        Getting BTS general information from Node B

        :param session: (optional) Session to use, can be an alias or
                        SessionHandler object.
        :param str attribute: (optional) attribute to return only specific info,
                              default value is None: all info returned
        :param timeout: (optional) Timeout for getting response, defaults to None (indefinite).

        :return: Dictionary with data.
        """
        return self.connection.get_bts_info(session=session, attribute=attribute, timeout=timeout)

    @web_connection_decorator
    def collect_snapshot(self, snapshot_dir, timeout=900):
        """
        Collect snapshot from the AirScale.

        :param snapshot_dir: full path to snapshot
        :param timeout: timeout for collecting snapshot
        :return: None
        """
        unix_local = UnixFunctionality(device_name="UnixLocal", autoconnect=True)
        unix_local.make_directory(path=snapshot_dir)

        now = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        file_name = "gNB_Snapshot_{}.zip".format(now)
        snapshot_path = os.path.join(snapshot_dir, file_name)

        self.connection.make_snapshot(snapshot_path=snapshot_path, timeout=timeout, rap=['RAP 1'])

    @web_connection_decorator
    def get_release_version(self):
        """
        Get release version.

        :return: release version
        """
        sw_release = self.connection.get_cbts_sw_release_name()
        return sw_release

    @web_connection_decorator
    def reset_and_wait_for_site(self):
        """
        Reset gNB and wait for it to be available.

        :return: None
        """
        self.connection.reset_and_wait_for_site()

    @web_connection_decorator
    def get_radio_module_info(self, **kwargs):
        """
        Get value(s) of given attribute (if provided) from fsm or whole json from frm as dictionary.

        :return: value(s) of given attribute from fsm, if attribute is None- returns whole json from frm as dictionary
        """
        return self.connection.get_frm(**kwargs)

    @web_connection_decorator
    def get_radio_module_availability_status(self):
        """
        Get value of availabilityStatus attribute from fsm.

        :return: value of availabilityStatus as string.
        """
        return self.connection.get_frm(attribute='availabilityStatus')

    @web_connection_decorator
    def get_current_commissioning(self, log_dir="/tmp/", scf_name="Current_SCF.xml"):
        """
        Get current configuration file from gNB.

        :return: path to saved commissioning file.
        """
        return self.connection.get_current_scf_file(log_dir, scf_name)

    @web_connection_decorator
    def cell_lock(self, cell_id=1):
        """
        Lock all cells in cell group by cell_id.
        :param cell_id (optional) Identity of the cell. Default equals 1.

        :return: None
        """
        self.connection.cell_lock(cell_id=cell_id)

    @web_connection_decorator
    def cell_unlock(self, cell_id=1):
        """
        Unlock all cells in cell group by cell_id.

        :return: None
        """
        self.connection.cell_unlock(cell_id=cell_id)

    @web_connection_decorator
    def get_cell_specific_info(self, cell_number=1, attribute=None):
        """
        Gets info about specific cell from given number.

        :param cell_number: the cell id, num 1 to 8 can be used, if None returns all cells info
        :param attribute: attribute name, should be written in camelcase style, like 'availabilityStatus'
        :return: cell's info if attribute is None or value from cell if attribute is not None
        """
        return self.connection.get_cell_specific_info(cell_number=cell_number, attribute=attribute)

    @web_connection_decorator
    def verify_cells_status(self):
        """
        Check if every cell is in status as planned in commissioning.

        :return: None
        """
        return self.connection.verify_cells_status()

    @web_connection_decorator
    def get_cell_status(self, *args, **kwargs):
        """
        Gets information about the cell status.

        :return: list of cells status
        """
        return self.connection.get_cell_status(*args, **kwargs)

    @web_connection_decorator
    def get_operational_state(self, dist_name):
        """
        Returns current operationalState of managed object from NIDD by given distName.
        :param dist_name: parameter group name
        :return: operationalState value as string
        """
        state_dict = self.connection.get_managed_object_state(dist_name=dist_name, status_name='operationalState')
        return state_dict['operationalState']

    @web_connection_decorator
    def update_software(self):
        """
        Software update via rest_api doesn't exist in megazone
        """
        raise MegazoneFunctionalityNotSupported("Software update via rest_api doesn't exist in megazone")

